// Extract target language and audio data
const body = $input.first().json.body || {};
const query = $input.first().json.query || {};
const targetLang = body.targetLang || query.targetLang || body.target || query.target || 'en';

// Get audio binary data
const audioBinary = $input.first().binary?.audio;

if (!audioBinary) {
  throw new Error('No audio data found in request');
}

// Log for debugging
console.log('Target language:', targetLang);
console.log('Audio data size:', audioBinary.data ? audioBinary.data.length : 'unknown');

return {
  json: { 
    targetLang: targetLang,
    audioInfo: {
      mimeType: audioBinary.mimeType,
      fileExtension: audioBinary.fileExtension,
      fileName: audioBinary.fileName || 'audio.webm'
    }
  },
  binary: { audio: audioBinary }
};

// Process the response from Flask Whisper service
const response = $input.first().json;

// Handle different response formats
let transcription = '';
let translatedText = '';
let sourceLanguage = 'unknown';
let targetLanguage = $('Extract Data').first().json.targetLang || 'en';

if (response.text) {
  // If it's just transcription, use it as both
  transcription = response.text;
  translatedText = response.text;
} else if (response.transcription) {
  transcription = response.transcription;
  translatedText = response.translation || response.transcription;
} else if (typeof response === 'string') {
  transcription = response;
  translatedText = response;
} else {
  // Try to extract any text from the response
  transcription = JSON.stringify(response);
  translatedText = transcription;
}

if (response.detected_language) {
  sourceLanguage = response.detected_language;
} else if (response.language) {
  sourceLanguage = response.language;
}

return {
  transcription: transcription,
  translatedText: translatedText,
  sourceLanguage: sourceLanguage,
  targetLanguage: targetLanguage,
  model: 'whisper-flask',
  device: 'cpu',
  originalResponse: response
};
